insert into public.station_challenge_definitions(id,code,version,grade_id,station_id,game_code,primary_skill_codes,supporting_skill_codes,objective,learning_role,rounds,difficulty_policy,hint_policy,timer_policy,evaluator_version,reward_policy,evidence_policy,estimated_duration_sec,status) select '2f050000-0000-4000-8000-000000000001','G1-ST01-CH-01',1,g.id,'21000000-0000-4000-8000-000000000001','G1-GAME-001','["G1-SK009","G1-SK010"]','["G1-SK011"]','الگو را ادامه بده تا راه پیدا شود','REVIEW',3,'{"mode":"STEP_ADAPTIVE","startLevel":"CORE","stepDownAfterWrongAttempts":2,"stepUpAfterFirstTryRounds":2,"preservesSkillIdentity":true}','{"ladder":["STRATEGY","REPRESENTATION","WORKED_STEP"],"offerAfterWrongAttempts":1,"offerAfterIdleMs":8000,"revealsFinalAnswer":false,"reducesReward":false}','NONE','st01-ch-pattern-v1','{"source":"CHALLENGE_COMPLETION","rewardClass":"STICKER","rewardDefinitionCode":"G1-R-ST01-CH","grantedOn":["COMPLETED","COMPLETED_WITH_SUPPORT"],"oncePerChallengeInstance":true,"replayGrants":false}','{"mode":"PRACTICE_EVIDENCE","countsTowardStationPass":false,"countsTowardMastery":false,"tagsScaffoldedAttempts":true}',60,'ACTIVE' from public.grades g where g.code='G1' on conflict(id) do update set status='ACTIVE';
insert into public.station_challenge_rounds(id,challenge_definition_id,round_index,skill_code) values ('2a050000-0000-4000-8000-000000000001','2f050000-0000-4000-8000-000000000001',0,'G1-SK009'),('2a050000-0000-4000-8000-000000000002','2f050000-0000-4000-8000-000000000001',1,'G1-SK010'),('2a050000-0000-4000-8000-000000000003','2f050000-0000-4000-8000-000000000001',2,'G1-SK011') on conflict(id) do update set skill_code=excluded.skill_code;
insert into public.station_challenge_variants(id,round_id,difficulty_level,content_version_id,skill_code) select gen_random_uuid(),r.id,v.level,v.cv,r.skill_code from public.station_challenge_rounds r join (values (0,'SUPPORTED','26050000-0000-4000-8000-000000000001'::uuid),(0,'CORE','26050000-0000-4000-8000-000000000002'::uuid),(0,'STRETCH','26050000-0000-4000-8000-000000000003'::uuid),(1,'SUPPORTED','26050000-0000-4000-8000-000000000004'::uuid),(1,'CORE','26050000-0000-4000-8000-000000000005'::uuid),(1,'STRETCH','26050000-0000-4000-8000-000000000006'::uuid),(2,'SUPPORTED','26050000-0000-4000-8000-000000000007'::uuid),(2,'CORE','26050000-0000-4000-8000-000000000008'::uuid),(2,'STRETCH','26050000-0000-4000-8000-000000000009'::uuid)) v(i,level,cv) on v.i=r.round_index where r.challenge_definition_id='2f050000-0000-4000-8000-000000000001' and not exists(select 1 from public.station_challenge_variants x where x.round_id=r.id and x.difficulty_level=v.level);
